+						});
+					} else if (detailTable === 'responses') {
+						items.push({
+							label: questionTitle || 'Response',
+							clickable: false
+						});
+					} else {
+						// Fallback for null detailTable
+						items.push({
+							label: questionTitle || 'Question',
+							clickable: false
+						});
+					}
+				}
+			} else if (detailTable === 'actions') {
+				items.push({
+					label: 'Actions',
