+				label: 'Email Preview',
+				clickable: false
+			});
+		}
+
+		return items;
+	});
+
+	// Cache the breadcrumb items to avoid multiple function calls
+	const items = $derived(breadcrumbItems());
+
+	// Always show breadcrumbs (at minimum shows current page)
